import{_ as d,a0 as r,w as i,s,ao as a,I as e,x as o,a1 as t,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"在linux中如何通过nload来监控网络使用情况 | LCTT x X-CMD","titleTemplate":false,"description":"在linux中如何通过nload来监控网络使用情况 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在linux中如何通过nload来监控网络使用情况 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在linux中如何通过nload来监控网络使用情况 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150121 How to Monitor Network Usage with nload in Linux","title":"在linux中如何通过nload来监控网络使用情况","tag":"201503","desc":""},"relativePath":"201503/20150121 How to Monitor Network Usage with nload in Linux.md","filePath":"[post].md"}'),g={name:"201503/20150121 How to Monitor Network Usage with nload in Linux.md"};function u(m,n,x,c,h,w){const l=r("Link");return i(),s("div",null,[n[16]||(n[16]=a(`<h1 id="在linux中如何通过nload来监控网络使用情况" tabindex="-1">在linux中如何通过nload来监控网络使用情况 <a class="header-anchor" href="#在linux中如何通过nload来监控网络使用情况" aria-label="Permalink to “在linux中如何通过nload来监控网络使用情况”">​</a></h1><p>nload 是一个 linux 自由软件工具，通过提供两个简单的图形来帮助linux用户和系统管理员来实时监控网络流量以及宽带使用情况：一个是进入流量，一个是流出流量。</p><p>我真的很喜欢用<strong>nload</strong>来在屏幕上显示当前的下载速度、总的流入量和平均下载速度等信息。nload工具的报告图非常容易理解，最重要的是这些信息真的非常有用。</p><p>在其使用手册上说到，在默认情况下它会监控所有网络设备。但是你可以轻松地指定你想要监控的设备，而且可以通过方向键在不同的网络设备之间进行转换。另外还有很多的选项可用，例如 ‘-t’选项以毫秒来设定刷新显示时间间隔（默认时间间隔值是500毫秒），‘-m’选项用来同时显示多个设备（在使用该选项时不会显示流量图），‘-u’选项用来设置显示流量数字的单位，另外还有许多其他的选项将会在本教程中探索和练习。</p><h3 id="如何将-nload安装到你的linux机器上" tabindex="-1">如何将 nload安装到你的linux机器上 <a class="header-anchor" href="#如何将-nload安装到你的linux机器上" aria-label="Permalink to “如何将 nload安装到你的linux机器上”">​</a></h3><p><strong>Ubuntu</strong> 和 <strong>Fedora</strong> 用户可以从默认的软件仓库中容易地安装。</p><p>在Ubuntu上使用以下命令进行安装。</p><pre><code>sudo apt-get install nload
</code></pre><p>在Fedora上使用以下命令进行安装。</p><pre><code>sudo yum install nload
</code></pre><p><strong>CentOS</strong>用户该怎么办呢？ 只需要在你的机器上输入以下命令就可以安装成功。</p><pre><code>sudo yum install nload
</code></pre><p>以下的命令会帮助你在OpenBSD系统中安装nload。</p><pre><code>sudo pkg_add -i nload
</code></pre><p>在 linux 机器上的另外一个非常有效的安装软件的方式就是编译源代码，下载并安装最新的版本意味着能够获得更好地性能、更酷的特性以及更少的bug。</p><h3 id="如何通过源代码安装nload" tabindex="-1">如何通过源代码安装nload <a class="header-anchor" href="#如何通过源代码安装nload" aria-label="Permalink to “如何通过源代码安装nload”">​</a></h3><p>在从源代码安装nload之前，你需要首先下载源代码。 我通常使用wget工具来进行下载--该工具在许多linux机器上默认可用。该免费工具帮助用户以非交互式的方式从网络上下载文件，并支持以下协议：</p><ul><li>HTTP</li><li>HTTPS</li><li>FTP</li></ul><p>通过以下命令来进入到<strong>/tmp</strong>目录中。</p><pre><code>cd /tmp
</code></pre><p>然后在你的终端中输入以下命令就可以将最新版本的nload下载到你的linux机器上了。</p><pre><code>wget http://www.roland-riegel.de/nload/nload-0.7.4.tar.gz
</code></pre>`,22)),e("p",null,[n[1]||(n[1]=o("如果你不喜欢使用wget工具，也可以通过简单的一个鼠标点击轻松地从",-1)),t(l,{href:"http://www.roland-riegel.de/nload/nload-0.7.4.tar.gz"},{default:p(()=>[...n[0]||(n[0]=[o("官网",-1)])]),_:1}),n[2]||(n[2]=o("上下载其源代码。",-1))]),n[17]||(n[17]=a(`<p>由于该软件非常轻巧，其下载过程几乎在瞬间就会完成。接下来的步骤就是通过<strong>tar</strong>工具来将下载的源代码包进行解压。</p><p>tar归档工具可以用来从磁带或硬盘文档中存储或解压文件，该工具有许多可用的选项，但是我们只需要下面的几个选项来执行我们的操作。</p><ol><li><strong>-x</strong> 从归档中解压文件</li><li><strong>-v</strong> 使用繁琐模式运行--用来显示详细信息</li><li><strong>-f</strong> 用来指定归档文件</li></ol><p>例如（LCTT 译注：tar 命令的参数前的“-”可以省略）：</p><pre><code>tar xvf example.tar
</code></pre><p>现在你学会了如何使用tar工具，我可以非常肯定你知道了如何从命令行中解压这个.tar文档。</p><pre><code>tar xvf nload-0.7.4.tar.gz
</code></pre><p>之后使用cd命令来进入到nload*目录中：</p><pre><code>cd nload*
</code></pre><p>在我的系统上看起来是这样的：</p><pre><code>oltjano@baby:/tmp/nload-0.7.4$
</code></pre><p>然后运行下面这个命令来为你的系统配置该软件包：</p><pre><code>./configure
</code></pre><p>此时会有“一大波僵尸”会在你的屏幕上显示出来，下面的一个屏幕截图描述了它的样子。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload1.png" alt="configuring packages for nload"></p><p>在上述命令完成之后，通过下面的命令来编译nload。</p><pre><code>make
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload2.png" alt="compiling nload"></p><p>好了，终于....，通过以下命令可以将nload安装在你的机器上了。</p><pre><code>sudo make install
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload3.png" alt="installing nload from source"></p><p>安装好nload之后就是让你学习如何使用它的时间了。</p><p>###如何使用nload###</p><p>我喜欢探索，所以在你的终端输入以下命令.</p><pre><code>nload
</code></pre><p>看到了什么？</p><p>我得到了下面的结果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.png" alt="running nload"></p><p>如上述截图可以看到,我得到了以下信息:</p><h4 id="流入量" tabindex="-1">流入量#### <a class="header-anchor" href="#流入量" aria-label="Permalink to “流入量####”">​</a></h4><p><strong>当前下载速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.1.png" alt="nload running on linux"></p><p><strong>平均下载速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.2.png" alt="nload running on linux"></p><p><strong>最小下载速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.3.png" alt="nload running on linux"></p><p><strong>最大下载速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.4.png" alt="nload running on linux"></p><p><strong>总的流入量按字节进行显示</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.5.png" alt=""></p><h4 id="流出量" tabindex="-1">流出量 <a class="header-anchor" href="#流出量" aria-label="Permalink to “流出量”">​</a></h4><p>类似的同样适用于流出量</p><h4 id="一些nload有用的选项" tabindex="-1">一些nload有用的选项#### <a class="header-anchor" href="#一些nload有用的选项" aria-label="Permalink to “一些nload有用的选项####”">​</a></h4><p>使用选项</p><pre><code>   -u
</code></pre><p>用来设置显示流量单位。</p><p>下面的命令会帮助你使用MBit/s显示单元</p><pre><code>nload -u m
</code></pre><p>下面的屏幕截图显示了上述命令的结果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload5.png" alt="nload running on linux"></p><p>尝试以下命令然后看看有什么结果。</p><pre><code>nload -u g
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload6.png" alt="nload running on linux"></p><p>同时还有一个<strong>-U</strong>选项。根据手册描述，该选项基本上与-u选项类似，只是用在合计数据。 我测试了这个命令，老实说，当你需要检查总的流入与流出量时非常有用。</p><pre><code>nload -U G
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload7.png" alt="nload running on linux"></p><p>从上面的截图中可以看到，<strong>nload -U G</strong> 使用Gbyte来显示数据总量。</p><p>另外一个我喜欢使用的有用选项是 <strong>-t</strong>。 该选项用来设置刷新显示事件间隔，单位为毫秒，默认值为500毫秒。</p><p>我会通过下面的命令做一些小的实验。</p><pre><code>nload -t 130
</code></pre><p>那么上述命令做了什么呢？它将刷新显示时间间隔设置为130毫秒。 通常推荐不要将该时间间隔值设置为小于100毫秒，因为nload在生成报告时计算错误。</p><p>另外的一个选项为 <strong>-a</strong>， 在你想要设置计算平均值的时间窗口的秒数时使用，默认该值为300秒。</p><p>那么当你想要监控指定的网络设备该如何呢？ 非常容易， 像下面这样简单地指定设备或者列出想要监控的设备列表即可。</p><pre><code>nload wlan0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload8.png" alt="nload monitoring wlan0 on linux"></p><p>下面的语法可帮助你监控指定的多个设备。</p><pre><code>nload [options] device1 device2 devicen
</code></pre><p>例如，使用下面的命令来监控eth0和eth1。</p><pre><code>nload wlan0 eth0
</code></pre><p>如果不带选项来运行nload，那么它会监控所有自动检测到的设备，你可以通过左右方向键来显示其中的任何一个设备的信息。</p><hr>`,71)),e("p",null,[n[4]||(n[4]=o("via: ",-1)),t(l,{href:"http://linoxide.com/monitoring-2/monitor-network-usage-nload/"},{default:p(()=>[...n[3]||(n[3]=[o("http://linoxide.com/monitoring-2/monitor-network-usage-nload/",-1)])]),_:1})]),e("p",null,[n[8]||(n[8]=o("作者：",-1)),t(l,{href:"http://linoxide.com/author/oltjano/"},{default:p(()=>[...n[5]||(n[5]=[o("Oltjano Terpollari",-1)])]),_:1}),n[9]||(n[9]=o(" 译者：",-1)),t(l,{href:"https://github.com/theo-l"},{default:p(()=>[...n[6]||(n[6]=[o("theo-l",-1)])]),_:1}),n[10]||(n[10]=o(" 校对：",-1)),t(l,{href:"https://github.com/wxy"},{default:p(()=>[...n[7]||(n[7]=[o("wxy",-1)])]),_:1})]),e("p",null,[n[13]||(n[13]=o("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[11]||(n[11]=[o("LCTT",-1)])]),_:1}),n[14]||(n[14]=o(" 原创翻译，",-1)),t(l,{href:"http://linux.cn/"},{default:p(()=>[...n[12]||(n[12]=[o("Linux中国",-1)])]),_:1}),n[15]||(n[15]=o(" 荣誉推出",-1))])])}const k=d(g,[["render",u]]);export{b as __pageData,k as default};
